import User from "./Users";
export const data = User.map((item)=>{
    return {
        id: item.id,
        name: item.firstName+" "+item.maidenName+" "+item.lastName,
        username: item.username,
        email: item.email,
        phone: item.phone,
        gender: item.gender,
        birthDate: item.birthDate,
        age: item.age,
        bloodGroup: item.bloodGroup,
    }
})
export const columns = [
    {
        accessorKey: "id",
        header: "ID",
        size: 100,
    },
    {
        accessorKey: "name",
        header: "Name",
    },
    {
        accessorKey: "username",
        header: "Username",
    },
    {
        accessorKey: "email",
        header: "Email",
    },
    {
        accessorKey: "phone",
        header: "Phone",
    },
    {
        accessorKey: "gender",
        header: "Gender",
    },
    {
        accessorKey: "birthDate",
        header: "Birth Date",
    },
    {
        accessorKey: "age",
        header: "Age",
    },
    {
        accessorKey: "bloodGroup",
        header: "Blood Group",
    }
]
